styles.tutorial:
section[data-skill-hub] .-w {
  display: grid;
  grid-template-columns: repeat(14, 1fr);
  grid-template-rows: repeat(17, auto);
  column-gap: var(--g-gap);
}

section[data-skill-hub] .poster {
  grid-column-start: 1;
  grid-column-end: 15;

  display: grid;
  grid-template-columns: repeat(10, 1fr);
  column-gap: var(--g-gap);
  align-items: start;

  margin-top: calc(var(--vh) * 70);
  margin-bottom: calc(var(--h1) * 2);
  color: #D7BDC9;

  position: relative;
}
section[data-skill-hub] .poster * {
  position: relative;
}
section[data-skill-hub] .image-bg {
  grid-column-start: 1;
  grid-column-end: 11;
  grid-row-start: 1;
  grid-row-end: 18;
  position: absolute;
  inset: 0;
  overflow: hidden;
  display: flex;
  justify-content: center;
  align-items: center;
}
section[data-skill-hub] .image-bg img {
  width: 100%;
  height: calc(100% + var(--vh,1vh) * 20);
  object-fit: cover;
  /* margin-top: calc(var(--vh,1vh) * -20);
  margin-bottom: calc(var(--vh,1vh) * -20); */
  /* inset: calc(var(--vh,1vh) * -20) 0 calc(var(--vh,1vh) * -20) 0; */
}

section[data-skill-hub] .top-center {
  grid-column-start: 1;
  grid-column-end: 11;
  grid-row-start: 1;
  grid-row-end: 2;
  justify-content: center;
  text-align: center;
  margin-top: calc(var(--vw,1vw) * 20);
}
section[data-skill-hub] .bottom-center {
  grid-column-start: 1;
  grid-column-end: 11;
  grid-row-start: 17;
  grid-row-end: 18;
  justify-content: center;
  text-align: center;
  margin-bottom: calc(var(--vw,1vw) * 20);
}
section[data-skill-hub] .decorative {
  grid-column-start: 1;
  grid-column-end: 11;
  grid-row-start: 1;
  grid-row-end: 2;
  justify-content: start;
  display: flex;
  gap: var(--g-gap);
  margin-top: calc(var(--vw,1vw) * 20);
  margin-left: var(--p);
}
section[data-skill-hub] .caption {
  grid-column-start: 8;
  grid-column-end: 10;
  grid-row-start: 2;
  grid-row-end: 3;
  max-width: 7rem;
  margin-top: calc(var(--vw,1vw) * 40);
  margin-bottom: calc(var(--vw,1vw) * 20);
}


section[data-skill-hub] .title {
  align-self: center;
  color: #E6DFE4;
  text-transform: uppercase;
  font-size: calc(var(--vw,1vw) * 11);
  line-height: 0.8;
}
section[data-skill-hub] .shaping {
  grid-column-start: 1;
  grid-column-end: 11;
  grid-row-start: 4;
  grid-row-end: 5;
  justify-self: start;
  color: var(--c-red);
  margin-left: var(--p);
}
section[data-skill-hub] .a {
  grid-column-start: 1;
  grid-column-end: 11;
  grid-row-start: 6;
  grid-row-end: 7;
  justify-self: start;
  color: var(--c-black);
  margin-left: var(--p);
}
section[data-skill-hub] .distinct {
  grid-column-start: 1;
  grid-column-end: 11;
  grid-row-start: 6;
  grid-row-end: 7;
  justify-self: right;
  text-align: right;
  margin-right: var(--p);
}
section[data-skill-hub] .identity {
  grid-column-start: 1;
  grid-column-end: 11;
  grid-row-start: 8;
  grid-row-end: 9;
  justify-self: left;
  margin-left: var(--p);
}
section[data-skill-hub] .through {
  grid-column-start: 1;
  grid-column-end: 10;
  grid-row-start: 10;
  grid-row-end: 11;
  justify-self: right;
  text-align: right;
  margin-right: var(--p);
}
section[data-skill-hub] .form {
  grid-column-start: 1;
  grid-column-end: 11;
  grid-row-start: 12;
  grid-row-end: 13;
  justify-self: left;
  margin-left: var(--p);
}
section[data-skill-hub] .and {
  grid-column-start: 1;
  grid-column-end: 10;
  grid-row-start: 12;
  grid-row-end: 13;
  justify-self: right;
  text-align: right;
  margin-right: var(--p);
}
section[data-skill-hub] .colour {
  grid-column-start: 1;
  grid-column-end: 11;
  grid-row-start: 14;
  grid-row-end: 15;
  justify-self: right;
  text-align: right;
  color: var(--c-black);
  margin-right: var(--p);
}

section[data-skill-hub] .decorative-1 {
  grid-column-start: 1;
  grid-column-end: 11;
  grid-row-start: 10;
  grid-row-end: 11;
  align-self: center;
  justify-self: left;
  margin-left: var(--p);
}
section[data-skill-hub] .decorative-2 {
  grid-column-start: 6;
  grid-column-end: 11;
  grid-row-start: 12;
  grid-row-end: 13;
  align-self: center;
  justify-self: left;
}

section[data-skill-hub] .description {
  grid-column-start: 4;
  grid-column-end: 8;
  grid-row-start: 16;
  grid-row-end: 17;
  text-align: center;
  margin-top: calc(var(--vw,1vw) * 20);
  margin-bottom: calc(var(--vw,1vw) * 20);
}

section[data-skill-hub] .line {
  grid-column-start: 1;
  grid-column-end: 11;
  border-bottom: 1px solid #E6DFE4;
  height: 0;
  margin-left: var(--p);
  margin-right: var(--p);
}
section[data-skill-hub] .line-1 {
  grid-row-start: 3;
  grid-row-end: 4;
}
section[data-skill-hub] .line-2 {
  grid-row-start: 5;
  grid-row-end: 6;
}
section[data-skill-hub] .line-3 {
  grid-row-start: 7;
  grid-row-end: 8;
}
section[data-skill-hub] .line-4 {
  grid-row-start: 9;
  grid-row-end: 10;
}
section[data-skill-hub] .line-5 {
  grid-row-start: 11;
  grid-row-end: 12;
}
section[data-skill-hub] .line-6 {
  grid-row-start: 13;
  grid-row-end: 14;
}
section[data-skill-hub] .line-7 {
  grid-row-start: 15;
  grid-row-end: 16;
}



section[data-skill-hub] .-splitted {
  display: flex;
  flex-wrap: wrap;
  overflow: hidden;
}
section[data-skill-hub] .-s-char {
  cursor: default;
  transform: translate3d(0, 120%, 0);
  will-change: transform;
}
section[data-skill-hub] .-splitted.-inview .-s-char {
  transform: translate3d(0, 0, 0);
  transition: transform 0.9s var(--easing-function);
  transition-delay: calc((var(--char-start) / 5) * 0.3s);
}



@media (max-width: 1024px) {
  section[data-skill-hub] .-m {
    font-size: var(--mm);
  }
}
@media (min-width: 1024px) {
  section[data-skill-hub] .poster {
    grid-column-start: 3;
    grid-column-end: 13;
    margin-top: calc(var(--vh) * 55);
  }
  section[data-skill-hub] .top-center {
    margin-top: calc(var(--vw,1vw) * 5);
  }
  section[data-skill-hub] .bottom-center {
    margin-bottom: calc(var(--vw,1vw) * 5);
  }
  section[data-skill-hub] .decorative {
    gap: var(--p);
    margin-top: calc(var(--vw,1vw) * 5);
  }
  section[data-skill-hub] .caption {
    margin-top: calc(var(--vw,1vw) * 10);
    margin-bottom: calc(var(--vw,1vw) * 5);
  }
  section[data-skill-hub] .title {
    font-size: calc(var(--vw,1vw) * 9);
  }
  section[data-skill-hub] .-s-char:hover {
    background-color: var(--c-black);
    color: #E6DFE4;
  }
  section[data-skill-hub] .description {
    margin-top: calc(var(--vw,1vw) * 5);
    margin-bottom: calc(var(--vw,1vw) * 5);
  }
}
